   581  /*
   582   * takes an arbitrary string and tries to interprets it based on the
   583   * known configuration handlers for all registered types.  May produce
   584   * inconsistent results when multiple tokens of the same name are
   585   * registered under different file types.
   586   */
   587
   588  /*
   589   * we allow = delimiters here
   590   */
   591  #define SNMP_CONFIG_DELIMETERS " \t="
   592
   593  static int
   594  snmp_config_when(char *line, int when)
   595  {
   596      char           *cptr, buf[STRINGMAX];
   597      struct config_line *lptr = NULL;
   598      struct config_files *ctmp = config_files;
   599      char           *st, *start_from, *end;
   600
   601      if (line == NULL) {
   602          config_perror("snmp_config() called with a null string.");
   603          return SNMPERR_GENERR;
   604      }
   605
   606      strlcpy(buf, line, STRINGMAX);
   607      cptr = strtok_r(buf, SNMP_CONFIG_DELIMETERS, &st);
   608      if (!cptr) {
   609          netsnmp_config_warn("Wrong format: %s", line);
   610          return SNMPERR_GENERR;
   611      }
   612      if (cptr[0] == '[') {
   613          if (cptr[strlen(cptr) - 1] != ']') {
   614              netsnmp_config_error("no matching ']' for type %s.", cptr + 1);
   615              return SNMPERR_GENERR;
   616          }
   617          cptr[strlen(cptr) - 1] = '\0';
   618          lptr = read_config_get_handlers(cptr + 1);
   619          if (lptr == NULL) {
   620              netsnmp_config_error("No handlers registered for type %s.",
   621                                   cptr + 1);
   622              return SNMPERR_GENERR;
   623          }
   624          cptr = strtok_r(NULL, SNMP_CONFIG_DELIMETERS, &st);
   625          netsnmp_assert(cptr);
   626          lptr = read_config_find_handler(lptr, cptr);
   627      } else {
   628          /*
   629           * we have to find a token
   630           */
   631          for (; ctmp != NULL && lptr == NULL; ctmp = ctmp->next)
   632              lptr = read_config_find_handler(ctmp->start, cptr);
   633      }
   634      if (lptr == NULL && netsnmp_ds_get_boolean(NETSNMP_DS_LIBRARY_ID,
   635                                            NETSNMP_DS_LIB_NO_TOKEN_WARNINGS)) {
   636          netsnmp_config_warn("Unknown token: %s.", cptr);
   637          return SNMPERR_GENERR;
   638      }
   639
   640      /*
   641       * use the original string instead since strtok_r messed up the original
   642       */
   643      end = line + strlen(line);
   644      start_from = line + (cptr - buf) + strlen(cptr) + 1;
   645      if (start_from > end)
   646          start_from = end;
   647      line = skip_white(start_from);
   648
   649      return (run_config_handler(lptr, cptr, line, when));
   650  }
