   652  int
   653  netsnmp_config(char *line)
   654  {
   655      int             ret = SNMP_ERR_NOERROR;
   656      DEBUGMSGTL(("snmp_config", "remembering line \"%s\"\n", line));
   657      netsnmp_config_remember(line);      /* always remember it so it's read
   658                                           * processed after a free_config()
   659                                           * call */
   660      if (netsnmp_ds_get_boolean(NETSNMP_DS_LIBRARY_ID,
   661                                 NETSNMP_DS_LIB_HAVE_READ_CONFIG)) {
   662          DEBUGMSGTL(("snmp_config", "  ... processing it now\n"));
   663          ret = snmp_config_when(line, NORMAL_CONFIG);
   664      }
   665      return ret;
   666  }
